		if($(".price-In:not(.priceFormat)").length){
			$(".price-In:not(.priceFormat)").priceFormat({
				thousandsSeparator: '.',
				clearOnEmpty: true,
				centsLimit: ""
			});
			$_document.on('input', '.price-In:not(.priceFormat)', function() {
				const $this = $(this);
				let val = $this.val();
				// Loại bỏ ký tự không hợp lệ trước khi format
				if(!$Core.util.isEmpty(val)){
					val = val.replace(/[^\d]/g, '');
					$this.val(val);
					// Gọi lại plugin để định dạng
					$this.priceFormat({
						thousandsSeparator: '.',
						clearOnEmpty: true,
						centsLimit: ""
					});
				}
			});
		}
		$("[data-toggle=ripple]").click(function(a) {
			var i = $(this);
			0 == i.find(".ripple-ink").length && i.prepend("<span class='ripple-ink'></span>");
			var t = i.find(".ripple-ink");
			if (t.removeClass("animate"), !t.height() && !t.width()) {
				var e = Math.max(i.outerWidth(), i.outerHeight());
				t.css({height: e,width: e})
			}
			var r = a.pageX - i.offset().left - t.width() / 2,
				h = a.pageY - i.offset().top - t.height() / 2,
				l = i.data("ripple-color");
			t.css({top: h + "px",left: r + "px",background: l}).addClass("animate")
		});
